#include <errno.h>
#include <fcntl.h>
#include <stdio.h>
#include <string.h>
#include <unistd.h>

int main(void) {
    int n = 0;
    for (;;) {
        int fd = open("/dev/null", O_RDONLY);
        if (fd < 0) {
            printf("opened %d files, then: %s (errno %d)\n", n, strerror(errno), errno);
            return 1;
        }
        n++;
    }
}

#include <fcntl.h>
#include <stdio.h>
#include <sys/wait.h>
#include <unistd.h>

static void readsome(const char *who, int fd) {
    char buf[7] = {0};
    int n = read(fd, buf, 6);
    if (n > 0 && buf[n - 1] == '\n') buf[n - 1] = 0;
    printf("%-8s read: %s\n", who, buf);
}

int main(void) {
    puts("-- one open(), then fork: parent and child share the offset");
    fflush(stdout);                    /* an unflushed buffer would be copied into the child */
    int fd = open("data.txt", O_RDONLY);
    if (fork() == 0) {
        readsome("child", fd);
        return 0;
    }
    wait(NULL);
    readsome("parent", fd);
    close(fd);

    puts("-- two separate open() calls: independent offsets");
    int a = open("data.txt", O_RDONLY), b = open("data.txt", O_RDONLY);
    readsome("fd a", a);
    readsome("fd b", b);
    return 0;
}
